function _getThesisBrain(){try{return JSON.parse(localStorage.getItem("horatio_thesis_v1")||"{}")}catch(e){return{}}}
function saveThesisBrain(){const t={title:(document.getElementById("thesis-title")?.value||"").trim(),researchField:(document.getElementById("thesis-field")?.value||"").trim(),centralArgument:(document.getElementById("thesis-central-argument")?.value||"").trim(),theoreticalFrameworks:(document.getElementById("thesis-frameworks")?.value||"").split("\n").map(s=>s.trim()).filter(Boolean),keyTensions:(document.getElementById("thesis-tensions")?.value||"").trim(),unresolvedQuestions:(document.getElementById("thesis-questions")?.value||"").trim(),recurringAuthors:(document.getElementById("thesis-authors")?.value||"").trim(),chapterMap:(document.getElementById("thesis-chapters")?.value||"").trim(),supervisorFeedback:(document.getElementById("thesis-feedback")?.value||"").trim(),supervisorName:(document.getElementById("thesis-supervisor")?.value||"").trim(),institution:(document.getElementById("thesis-institution")?.value||"").trim(),targetCompletion:(document.getElementById("thesis-completion")?.value||"").trim()};localStorage.setItem("horatio_thesis_v1",JSON.stringify(t));if(typeof window.brainAPI!=="undefined"){window.brainAPI.setThesis({title:t.title,statement:t.centralArgument,researchQuestions:t.unresolvedQuestions?t.unresolvedQuestions.split("\n").map(s=>s.trim()).filter(Boolean):[],keyConcepts:t.theoreticalFrameworks||[],discipline:t.researchField}).catch(()=>{})}addBubble("system","Thesis Brain saved. Horatio will use this as ground truth in all sessions.")}
function loadThesisUI(){const t=_getThesisBrain();const fields={"thesis-title":t.title,"thesis-field":t.researchField,"thesis-central-argument":t.centralArgument,"thesis-frameworks":(t.theoreticalFrameworks||[]).join("\n"),"thesis-tensions":t.keyTensions,"thesis-questions":t.unresolvedQuestions,"thesis-authors":t.recurringAuthors,"thesis-chapters":t.chapterMap,"thesis-feedback":t.supervisorFeedback,"thesis-supervisor":t.supervisorName,"thesis-institution":t.institution,"thesis-completion":t.targetCompletion};Object.entries(fields).forEach(([id,val])=>{const el=document.getElementById(id);if(el)el.value=val||""})}
function _getMemory(){try{return JSON.parse(localStorage.getItem("horatio_memory_v1")||"[]")}catch(e){return[]}}
function _saveMemory(nodes){localStorage.setItem("horatio_memory_v1",JSON.stringify(nodes));renderMemoryPanels()}
function _pruneMemory(nodes){return nodes.length>200?nodes.slice(-150):nodes}
async function _extractMemoryFromSession(){if(!chatHistory||!chatHistory.length)return;const recent=chatHistory.slice(-10).map(e=>e.role+": "+String(e.text||"").slice(0,800)).join("\n\n");const prompt="You are a research memory extractor for a PhD student using an AI supervisor. From the following supervision conversation extract 2-3 key research memory nodes. Each node must be typed as one of: insight, argument, decision, source, question.\n\nRespond with ONLY a valid JSON array, no other text:\n[{\"type\":\"insight\",\"content\":\"concise note here\"},{\"type\":\"argument\",\"content\":\"concise note here\"}]\n\nConversation:\n"+recent;try{const raw=await _callToolAI(prompt);const text=(raw||"").replace(/^```json\s*/,"").replace(/\s*```$/,"").trim();const parsed=JSON.parse(text);if(Array.isArray(parsed)&&parsed.length){const existing=_getMemory();const ts=new Date().toISOString().slice(0,10);const newNodes=parsed.filter(n=>n&&n.content).map(n=>({type:n.type||"insight",content:String(n.content).trim(),date:ts}));const updated=_pruneMemory([...existing,...newNodes]);_saveMemory(updated)}}catch(e){}}
function renderMemoryPanels(){const nodes=_getMemory();const typeColors={insight:"#14b8a6",argument:"#6366f1",decision:"#f59e0b",source:"#3b82f6",question:"#ef4444"};const makeHtml=()=>nodes.length?nodes.slice().reverse().map((n,i)=>{const realIdx=nodes.length-1-i;const col=typeColors[n.type]||"#14b8a6";return`<div class="mem-node"><div class="mem-node-body"><span class="mem-type-badge" style="color:${col};background:${col}22;border:1px solid ${col}44">${n.type||"insight"}</span>${String(n.content||"").replace(/</g,"&lt;").replace(/>/g,"&gt;")}<div class="mem-node-meta">${n.date||""}</div></div><button class="mem-del-btn" onclick="deleteMemoryNode(${realIdx})" title="Delete">×</button></div>`}).join(""):"<p class=\"s-note\" style=\"padding:1rem 0;\">No memory nodes yet. Memories are extracted automatically every 5 Horatio responses, or click Extract Now.</p>";const countText=nodes.length+" node"+(nodes.length!==1?"s":"");const cfgList=document.getElementById("cfg-mem-list");if(cfgList)cfgList.innerHTML=makeHtml();const cfgCount=document.getElementById("cfg-mem-count");if(cfgCount)cfgCount.textContent=countText;const navList=document.getElementById("nav-mem-list");if(navList)navList.innerHTML=makeHtml();const navCount=document.getElementById("nav-mem-count");if(navCount)navCount.textContent=countText}
function deleteMemoryNode(idx){const nodes=_getMemory();nodes.splice(idx,1);_saveMemory(nodes)}
function clearAllMemory(){if(!confirm("Clear all research memory nodes? This cannot be undone."))return;_saveMemory([])}
async function extractMemoryNow(){const btns=[document.getElementById("mem-extract-btn"),document.getElementById("nav-mem-extract-btn")];btns.forEach(b=>{if(b){b.disabled=true;b.innerHTML="<span class=\"horatio-spin\"></span>Extracting..."}});try{await _extractMemoryFromSession()}catch(e){}finally{btns.forEach(b=>{if(b){b.disabled=false;b.textContent="Extract Now"}})}}
function openCfgTab(tab){document.querySelectorAll(".cfg-tab").forEach(b=>b.classList.toggle("active",b.dataset.tab===tab));document.querySelectorAll(".cfg-pane").forEach(p=>p.classList.toggle("active",p.id==="cfg-pane-"+tab));if(tab==="thesis")loadThesisUI();if(tab==="memory")renderMemoryPanels()}

// ── Settings redesign JS ────────────────────────────────────────────────

const CFG_MODE_GROUPS = [
  { group: 'Research',   color: '#60a5fa',        modes: ['Critique','Sources','Consistency','Gap Analysis'] },
  { group: 'Writing',    color: 'var(--accent)',  modes: ['Draft','Expand','Summarise','Footnotes'] },
  { group: 'Assessment', color: '#818cf8',        modes: ['Viva Prep','Supervisor Report','Examiner View'] },
  { group: 'Utilities',  color: '#f59e0b',        modes: ['OSCOLA Cite','Argument Map','Database Search'] },
];

const CFG_PROVIDERS = [
  { id:'gemini',     label:'✦ Gemini'     },
  { id:'claude',     label:'◉ Claude'     },
  { id:'groq',       label:'⚡ Groq'       },
  { id:'openai',     label:'⊛ ChatGPT'   },
  { id:'perplexity', label:'◆ Perplexity' },
  { id:'ollama',     label:'⬡ Ollama'     },
];

const CFG_MODELS = {
  gemini:     ['gemini-2.5-flash','gemini-2.5-pro','gemini-2.5-flash'],
  claude:     ['claude-opus-4-7','claude-sonnet-4-6','claude-haiku-4-5-20251001'],
  groq:       ['meta-llama/llama-4-scout-17b-16e-instruct','llama-3.3-70b-versatile','llama-3.1-8b-instant'],
  openai:     ['gpt-4.1','gpt-4.1-mini','o4-mini'],
  perplexity: ['sonar-pro','sonar-deep-research','sonar-reasoning-pro','sonar'],
  ollama:     [localStorage.getItem('horatio_model_ollama')||'phi4-mini'],
};

function _modeSlug(mode){ return mode.toLowerCase().replace(/\s+/g,'-'); }

function _costColor(model=''){
  const m=model.toLowerCase();
  if(m.includes('flash')||m.includes('mini')||m.includes('haiku')||m.includes('llama')||m.includes('gemma')||m.includes('phi')||m.includes('8b')) return '#4ade80';
  if(m.includes('pro')||m.includes('opus')||m.includes('gpt-4')||m.includes('sonar-pro')||m.includes('70b')||m.includes('o4')) return '#f59e0b';
  return 'var(--text-3)';
}

function _loadModeCfg(mode){
  const slug=_modeSlug(mode);
  try{ return JSON.parse(localStorage.getItem('horatio_mode_cfg_'+slug)||'null'); }catch{ return null; }
  return null;
}

function _saveModeCfg(mode,provider,model){
  localStorage.setItem('horatio_mode_cfg_'+_modeSlug(mode), JSON.stringify({provider,model}));
}

function renderModeMatrix(){
  const el=document.getElementById('cfg-mode-matrix');
  if(!el) return;
  let html='<div class="cfgs-matrix-headers"><div class="cfgs-matrix-hcell">Mode</div><div class="cfgs-matrix-hcell">Provider</div><div class="cfgs-matrix-hcell">Model</div><div></div></div>';
  CFG_MODE_GROUPS.forEach(g=>{
    html+=`<div class="cfgs-matrix-group"><div class="cfgs-matrix-group-label" style="color:${g.color};border-color:${g.color}30;">${g.group}</div>`;
    g.modes.forEach(mode=>{
      const slug=_modeSlug(mode);
      const saved=_loadModeCfg(mode);
      const prov=saved?.provider||'groq';
      const mdls=CFG_MODELS[prov]||CFG_MODELS.groq;
      const mdl=saved?.model||mdls[0];
      const provOpts=CFG_PROVIDERS.map(p=>`<option value="${p.id}"${p.id===prov?' selected':''}>${p.label}</option>`).join('');
      const mdlOpts=mdls.map(m=>`<option value="${m}"${m===mdl?' selected':''}>${m}</option>`).join('');
      const costCol=_costColor(mdl);
      html+=`<div class="cfgs-matrix-row">
        <div class="cfgs-matrix-mode">${mode}</div>
        <select class="cfgs-select" onchange="onCfgsProvChange('${slug}',this.value)" data-mode="${slug}">${provOpts}</select>
        <select class="cfgs-select" onchange="_saveModeCfg('${mode}',document.querySelector('[data-mode=\\'${slug}\\']').value,this.value)" data-mode-model="${slug}">${mdlOpts}</select>
        <div class="cfgs-cost-dot" style="background:${costCol};" title="${_costColor(mdl)==='#4ade80'?'Fast/free':_costColor(mdl)==='#f59e0b'?'Deep/paid':'Standard'}"></div>
      </div>`;
    });
    html+='</div>';
  });
  el.innerHTML=html;
}

function onCfgsProvChange(slug,prov){
  const mdls=CFG_MODELS[prov]||CFG_MODELS.groq;
  const sel=document.querySelector(`[data-mode-model="${slug}"]`);
  if(sel){ sel.innerHTML=mdls.map(m=>`<option value="${m}">${m}</option>`).join(''); }
  const costDot=sel?.closest('.cfgs-matrix-row')?.querySelector('.cfgs-cost-dot');
  if(costDot){ const col=_costColor(mdls[0]); costDot.style.background=col; }
  // save with new provider's first model
  const modeEl=document.querySelector(`[data-mode="${slug}"]`);
  const modeName=CFG_MODE_GROUPS.flatMap(g=>g.modes).find(m=>_modeSlug(m)===slug)||slug;
  _saveModeCfg(modeName,prov,mdls[0]);
}

function toggleCfgSection(key){
  const body=document.getElementById('cfgs-body-'+key);
  const caret=document.getElementById('cfgs-caret-'+key);
  if(!body) return;
  const open=body.style.display!=='none';
  body.style.display=open?'none':'block';
  if(caret) caret.style.transform=open?'':'rotate(180deg)';
}

function toggleCfgsProv(id){
  const body=document.getElementById('cfgs-prov-body-'+id);
  const card=document.getElementById('cfgs-prov-'+id);
  if(!body) return;
  const open=body.style.display!=='none';
  body.style.display=open?'none':'block';
  card?.classList.toggle('open',!open);
}

function toggleBrainFeature(key){
  const btn=document.getElementById('toggle-brain-'+key);
  if(!btn) return;
  const on=btn.getAttribute('data-on')!=='true';
  btn.setAttribute('data-on',on?'true':'false');
  localStorage.setItem('horatio_brain_'+key, on?'1':'0');
}

function _getBrainFeature(key){ return localStorage.getItem('horatio_brain_'+key)!=='0'; }

function _loadNewSettingsUI(){
  // Scholar Persona
  const sp=document.getElementById('cfg-scholar-persona');
  if(sp) sp.value=localStorage.getItem('horatio_scholar_persona')||'';
  // Provider status dots
  const keyMap={gemini:'horatio_api_key',claude:'horatio_claude_key',openai:'horatio_openai_key',perplexity:'horatio_perplexity_key'};
  ['gemini','claude','groq','openai','perplexity','ollama'].forEach(id=>{
    const dot=document.getElementById('cfgs-dot-'+id);
    if(!dot) return;
    let configured=false;
    if(id==='ollama'||id==='groq') configured=true;
    else{ const sk=Object.entries({gemini:SK_KEY,claude:SK_CLAUDE_KEY,openai:SK_OPENAI_KEY,perplexity:SK_PERPLEXITY_KEY}); configured=sk.some(([k,v])=>k===id&&!!localStorage.getItem(v)); }
    dot.className='cfgs-status-dot'+(configured?' cfgs-status-dot-on':'');
  });
  // Key inputs (masked)
  const keyInputs=[
    ['cfg-key',SK_KEY],['cfg-claude-key',SK_CLAUDE_KEY],['cfg-groq-key',SK_GROQ_KEY],
    ['cfg-openai-key',SK_OPENAI_KEY],['cfg-perplexity-key',SK_PERPLEXITY_KEY]
  ];
  keyInputs.forEach(([id,sk])=>{ const el=document.getElementById(id); if(el&&localStorage.getItem(sk)) el.value='••••••••••••••••'; });
  // Mode matrix
  renderModeMatrix();
  // Brain toggles
  ['mem','proactive','session'].forEach(k=>{
    const btn=document.getElementById('toggle-brain-'+k);
    if(btn){ const on=_getBrainFeature(k); btn.setAttribute('data-on',on?'true':'false'); }
  });
  // Thesis fields
  loadThesisUI();
  // Response behaviour
  const rv=document.getElementById('cfg-resp-length'); if(rv) rv.value=localStorage.getItem('horatio_resp_length')||'balanced';
  const cs=document.getElementById('cfg-cite-style'); if(cs) cs.value=localStorage.getItem('horatio_cite_style')||'oscola';
  const ci=document.getElementById('cfg-critique-intensity'); if(ci) ci.value=localStorage.getItem('horatio_critique_intensity')||'rigorous';
  const vc=document.getElementById('cfg-voice'); if(vc) vc.value=localStorage.getItem('horatio_voice_name')||'Charon';
  // Context/temp sliders
  const ctx=document.getElementById('cfg-context'); if(ctx){ ctx.value=localStorage.getItem('horatio_context_window')||6; document.getElementById('cfg-context-val').textContent=ctx.value; }
  const tmp=document.getElementById('cfg-temp'); if(tmp){ tmp.value=localStorage.getItem('horatio_temperature')||0.7; document.getElementById('cfg-temp-val').textContent=parseFloat(tmp.value).toFixed(1); }
  // Advanced
  const pro=document.getElementById('cfg-pro'); if(pro&&(window.keystoreAPI?.get(SK_PRO)??localStorage.getItem(SK_PRO))) pro.value='••••••••••••••••';
  const fb=document.getElementById('cfg-fb-pass'); if(fb&&(window.keystoreAPI?.get(SK_FB_PASS)??localStorage.getItem(SK_FB_PASS))) fb.value='••••••••••••••••';
  const se=document.getElementById('cfg-sup-email'); if(se) se.value=localStorage.getItem(SK_SUP_EMAIL)||'';
  const ec=document.getElementById('cfg-ext-context'); if(ec) ec.value=localStorage.getItem(SK_EXT_CONTEXT)||'';
  const zk=document.getElementById('cfg-zotero-key'); if(zk&&localStorage.getItem('horatio_zotero_key')) zk.value='••••••••••••••••';
  const zu=document.getElementById('cfg-zotero-uid'); if(zu) zu.value=localStorage.getItem('horatio_zotero_uid')||'';
  updateStorageMeter();
}


function _markLatestBubble(){
  // Remove bounce from all Horatio icons, then re-add to the last one only
  const icons=document.querySelectorAll('#chat-stage .bubble.horatio .role-tag-icon');
  icons.forEach(el=>el.classList.remove('bouncing'));
  if(icons.length>0) icons[icons.length-1].classList.add('bouncing');
}

